-- MyReview 多用户存储（PostgreSQL）。启动时由 spring.sql.init 执行，全部幂等。
-- v2：所有主键改为自增 BIGINT（GENERATED BY DEFAULT AS IDENTITY），外键同步为 BIGINT。
-- 列名与 domain 实体字段 1:1 对应（camelCase → snake_case）；JsonNode 字段一律 text，epoch 毫秒一律 bigint。

CREATE TABLE IF NOT EXISTS users (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username        varchar(64)  NOT NULL UNIQUE,
    password_hash   varchar(512) NOT NULL,
    nickname        varchar(64),
    avatar_ext      varchar(8),
    -- API Key：AES-256-GCM 密文（主密钥在 E:/m_review/master.key，不入库不入仓库）
    api_key_cipher  text,
    api_key_nonce   text,
    api_key_version int,
    api_key_last4   varchar(8),
    -- 用户级 LLM 配置（null=用服务端默认）
    api_base        text,
    model           text,
    api_format      varchar(16),
    temperature     double precision,
    -- 个人求职总结 + 后台生成任务状态
    summary_json       text,
    summary_at         bigint,
    summary_status     varchar(16),
    summary_error      text,
    summary_started_at bigint,
    created_at      bigint NOT NULL,
    updated_at      bigint NOT NULL
);

-- 登录 token（只存 SHA-256 哈希，不存明文；默认 6 小时过期）
CREATE TABLE IF NOT EXISTS auth_token (
    token_hash varchar(64) PRIMARY KEY,
    user_id    bigint NOT NULL,
    created_at bigint NOT NULL,
    expires_at bigint NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_auth_token_user ON auth_token (user_id);
CREATE INDEX IF NOT EXISTS idx_auth_token_expires ON auth_token (expires_at);

CREATE TABLE IF NOT EXISTS stage (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      bigint NOT NULL,
    name         text NOT NULL,
    status       varchar(16),
    summary_json text,
    created_at   bigint NOT NULL,
    updated_at   bigint NOT NULL,
    completed_at bigint
);
CREATE INDEX IF NOT EXISTS idx_stage_user ON stage (user_id, updated_at);

CREATE TABLE IF NOT EXISTS practice (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         bigint NOT NULL,
    stage_id        bigint,
    mode            varchar(16),
    topic           text,
    scope_mode      varchar(16),
    scope_text      text,
    level           varchar(16),
    intensity       varchar(16),
    paper_size      int,
    review          boolean NOT NULL DEFAULT false,
    status          varchar(16),
    memory_json     text,
    notes_text      text,
    notes_updated_at bigint,
    digest_json     text,
    created_at      bigint NOT NULL,
    updated_at      bigint NOT NULL,
    completed_at    bigint
);
CREATE INDEX IF NOT EXISTS idx_practice_user_stage ON practice (user_id, stage_id);
CREATE INDEX IF NOT EXISTS idx_practice_stage ON practice (stage_id);

CREATE TABLE IF NOT EXISTS paper (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          bigint NOT NULL,
    practice_id      bigint NOT NULL,
    sequence         int NOT NULL,
    kind             varchar(16),
    focus_points_json text,
    composition_mode varchar(16),
    status           varchar(16),
    summary_json     text,
    progress_json    text,
    plan_json        text,
    max_score        int,
    created_at       bigint NOT NULL,
    submitted_at     bigint
);
-- 考试模式的题型数量 {"single":n,"multi":n,"blank":n,"shortAnswer":n,"code":n}
ALTER TABLE paper ADD COLUMN IF NOT EXISTS exam_mix_json text;
CREATE INDEX IF NOT EXISTS idx_paper_user_practice ON paper (user_id, practice_id, sequence);

CREATE TABLE IF NOT EXISTS question (
    id                   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id              bigint NOT NULL,
    practice_id          bigint,
    paper_id             bigint NOT NULL,
    sequence             int NOT NULL,
    prompt               text,
    reference_answer     text,
    knowledge_points_json text,
    demands_json         text,
    assigned_points_json text,
    angle                text,
    tier                 varchar(8),
    question_type        varchar(16),
    points               int,
    revealed_at          bigint,
    created_at           bigint NOT NULL
);
-- 考试模式：题型（single/multi/blank/short/code）+ 选项/结构化答案
ALTER TABLE question ADD COLUMN IF NOT EXISTS qtype varchar(16);
ALTER TABLE question ADD COLUMN IF NOT EXISTS options_json text;
ALTER TABLE question ADD COLUMN IF NOT EXISTS answer_json text;
CREATE INDEX IF NOT EXISTS idx_question_user_paper ON question (user_id, paper_id, sequence);
CREATE INDEX IF NOT EXISTS idx_question_user_practice ON question (user_id, practice_id, sequence);

CREATE TABLE IF NOT EXISTS attempt (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         bigint NOT NULL,
    question_id     bigint NOT NULL,
    sequence        int NOT NULL,
    answer          text,
    score           double precision,
    points          double precision,
    feedback        text,
    dimensions_json text,
    submitted_at    bigint NOT NULL,
    evaluated_at    bigint
);
CREATE INDEX IF NOT EXISTS idx_attempt_user_question ON attempt (user_id, question_id, sequence);

CREATE TABLE IF NOT EXISTS follow_up (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     bigint NOT NULL,
    practice_id bigint,
    question_id bigint NOT NULL,
    role        varchar(16),
    content     text,
    created_at  bigint NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_followup_user_question ON follow_up (user_id, question_id, created_at);

CREATE TABLE IF NOT EXISTS knowledge_point (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      bigint NOT NULL,
    practice_id  bigint NOT NULL,
    category     varchar(40),
    name         varchar(80),
    source       varchar(16),
    in_scope     boolean NOT NULL DEFAULT true,
    priority     varchar(16),
    evidence_json text,
    bound_quick  text,
    bound_std    text,
    bound_deep   text,
    times_seen   int,
    history_json text,
    angles_json  text,
    mastery      double precision,
    status       varchar(16),
    created_at   bigint NOT NULL,
    updated_at   bigint NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_kp_user_practice ON knowledge_point (user_id, practice_id, created_at);

CREATE TABLE IF NOT EXISTS memory_point (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          bigint NOT NULL,
    practice_id      bigint NOT NULL,
    question_id      bigint,
    point_names_json text,
    text             text,
    created_at       bigint NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_mp_user_practice ON memory_point (user_id, practice_id, created_at);

CREATE TABLE IF NOT EXISTS mistake (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     bigint NOT NULL,
    practice_id bigint NOT NULL,
    question_id bigint NOT NULL,
    source      varchar(16),
    reason      text,
    score       double precision,
    status      varchar(16),
    resolved_at bigint,
    created_at  bigint NOT NULL,
    updated_at  bigint NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_mistake_user_practice ON mistake (user_id, practice_id, created_at);

CREATE TABLE IF NOT EXISTS note (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     bigint NOT NULL,
    practice_id bigint NOT NULL,
    question_id bigint,
    scene       varchar(16),
    text        text,
    created_at  bigint NOT NULL,
    updated_at  bigint NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_note_user_practice ON note (user_id, practice_id, created_at);

CREATE TABLE IF NOT EXISTS review_doc (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      bigint NOT NULL,
    practice_id  bigint NOT NULL,
    status       varchar(16),
    -- v3 前的遗留大字段：整份学习卡 JSON（~30KB）。已迁移到 review_card，应用不再读写
    content_json text,
    progress_json text,
    created_at   bigint NOT NULL,
    updated_at   bigint NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_reviewdoc_user_practice ON review_doc (user_id, practice_id);

-- 复习提纲学习卡：一份提纲按知识点一行（替代 review_doc.content_json 整块大字段）
CREATE TABLE IF NOT EXISTS review_card (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      bigint NOT NULL,
    review_doc_id bigint NOT NULL,
    point_name   varchar(80) NOT NULL,
    category     varchar(40),
    priority     varchar(16),
    content_json text,
    sequence     int NOT NULL,
    created_at   bigint NOT NULL,
    updated_at   bigint NOT NULL,
    UNIQUE (review_doc_id, point_name)
);
CREATE INDEX IF NOT EXISTS idx_review_card_doc ON review_card (review_doc_id, sequence);

-- 网页抓取缓存：全局共享（URL 唯一，多用户复用省抓取）
CREATE TABLE IF NOT EXISTS source (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    url        varchar(1024) NOT NULL UNIQUE,
    title      text,
    text       text,
    fetched_at bigint,
    error      text
);

-- 迁移标记等元数据
CREATE TABLE IF NOT EXISTS app_meta (
    key   varchar(64) PRIMARY KEY,
    value text
);

-- ============================================================
-- 表 / 字段注释（COMMENT 幂等，每次启动覆盖写入）
-- ============================================================

COMMENT ON TABLE users IS '用户：登录账号、个人资料、加密的 API Key、求职总结与生成任务状态';
COMMENT ON COLUMN users.id IS '主键（自增）';
COMMENT ON COLUMN users.username IS '登录名，全局唯一';
COMMENT ON COLUMN users.password_hash IS '口令哈希（Argon2id，含盐与参数）';
COMMENT ON COLUMN users.nickname IS '昵称';
COMMENT ON COLUMN users.avatar_ext IS '头像文件扩展名（文件在 data-dir/avatars/{id}.{ext}）';
COMMENT ON COLUMN users.api_key_cipher IS 'API Key 密文（AES-256-GCM，Base64）';
COMMENT ON COLUMN users.api_key_nonce IS 'API Key 加密随机 nonce（Base64）';
COMMENT ON COLUMN users.api_key_version IS 'API Key 加密密钥版本（预留轮换）';
COMMENT ON COLUMN users.api_key_last4 IS 'API Key 末 4 位（仅掩码回显）';
COMMENT ON COLUMN users.api_base IS '用户级 LLM API Base（空=服务端默认）';
COMMENT ON COLUMN users.model IS '用户级模型名（空=服务端默认）';
COMMENT ON COLUMN users.api_format IS '用户级接口协议 anthropic/openai（空=服务端默认）';
COMMENT ON COLUMN users.temperature IS '用户级温度（空=服务端默认）';
COMMENT ON COLUMN users.summary_json IS '个人求职总结 JSON';
COMMENT ON COLUMN users.summary_at IS '求职总结生成时间（epoch ms）';
COMMENT ON COLUMN users.summary_status IS '求职总结任务状态 idle/generating/failed';
COMMENT ON COLUMN users.summary_error IS '求职总结任务失败原因';
COMMENT ON COLUMN users.summary_started_at IS '求职总结任务开始时间（epoch ms，用于判卡死）';
COMMENT ON COLUMN users.created_at IS '创建时间（epoch ms）';
COMMENT ON COLUMN users.updated_at IS '更新时间（epoch ms）';

COMMENT ON TABLE auth_token IS '登录 token：只存 SHA-256 哈希，默认 6 小时过期';
COMMENT ON COLUMN auth_token.token_hash IS 'token 的 SHA-256 十六进制（主键，不存明文）';
COMMENT ON COLUMN auth_token.user_id IS '归属用户';
COMMENT ON COLUMN auth_token.created_at IS '签发时间（epoch ms）';
COMMENT ON COLUMN auth_token.expires_at IS '过期时间（epoch ms）';

COMMENT ON TABLE stage IS '阶段：仅用于分组的名字，无业务含义';
COMMENT ON COLUMN stage.id IS '主键（自增）';
COMMENT ON COLUMN stage.user_id IS '归属用户';
COMMENT ON COLUMN stage.name IS '阶段名称';
COMMENT ON COLUMN stage.status IS '状态 active/completed';
COMMENT ON COLUMN stage.summary_json IS '阶段总结 JSON（overall/strengths/keyWeaknesses/nextSteps/reviewScope）';
COMMENT ON COLUMN stage.created_at IS '创建时间（epoch ms）';
COMMENT ON COLUMN stage.updated_at IS '更新时间（epoch ms）';
COMMENT ON COLUMN stage.completed_at IS '完成时间（epoch ms，可空）';

COMMENT ON TABLE practice IS '练习（会话）：一个范围练到底，可反复出卷';
COMMENT ON COLUMN practice.id IS '主键（自增）';
COMMENT ON COLUMN practice.user_id IS '归属用户';
COMMENT ON COLUMN practice.stage_id IS '所属阶段';
COMMENT ON COLUMN practice.mode IS '练习模式（interview）';
COMMENT ON COLUMN practice.topic IS '短标题';
COMMENT ON COLUMN practice.scope_mode IS '范围模式 topic/range';
COMMENT ON COLUMN practice.scope_text IS '范围模式下用户填写的范围原文';
COMMENT ON COLUMN practice.level IS '岗位难度 junior/mid/senior';
COMMENT ON COLUMN practice.intensity IS '复习强度 quick/standard/deep';
COMMENT ON COLUMN practice.paper_size IS '常规卷题量 6/10/15';
COMMENT ON COLUMN practice.review IS '是否系统发起的全复习练习';
COMMENT ON COLUMN practice.status IS '状态 active/completed';
COMMENT ON COLUMN practice.memory_json IS 'L1 长期记忆 JSON（已掌握/薄弱点/误区/下一步/已覆盖）';
COMMENT ON COLUMN practice.notes_text IS '记事本全文（一整块可编辑文本）';
COMMENT ON COLUMN practice.notes_updated_at IS '记事本最后修改时间（epoch ms）';
COMMENT ON COLUMN practice.digest_json IS 'L2 会话摘要 JSON';
COMMENT ON COLUMN practice.created_at IS '创建时间（epoch ms）';
COMMENT ON COLUMN practice.updated_at IS '更新时间（epoch ms）';
COMMENT ON COLUMN practice.completed_at IS '完成时间（epoch ms，可空）';

COMMENT ON TABLE paper IS '卷：AI 一次出的一批题，满分 100';
COMMENT ON COLUMN paper.id IS '主键（自增）';
COMMENT ON COLUMN paper.user_id IS '归属用户';
COMMENT ON COLUMN paper.practice_id IS '所属练习';
COMMENT ON COLUMN paper.sequence IS '练习内第几张卷（从 1 开始）';
COMMENT ON COLUMN paper.kind IS '卷类型 normal/final（期末考）/mistake（错题重做）';
COMMENT ON COLUMN paper.focus_points_json IS '错题卷锁定的知识点名 JSON 数组';
COMMENT ON COLUMN paper.composition_mode IS '组卷模式 regular/concept/scene';
COMMENT ON COLUMN paper.status IS '状态 generating/answering/grading/graded';
COMMENT ON COLUMN paper.summary_json IS '本卷总结 JSON';
COMMENT ON COLUMN paper.progress_json IS '后台任务进度 JSON（出题/批改中）';
COMMENT ON COLUMN paper.plan_json IS '出卷计划 JSON（断点续跑依据）';
COMMENT ON COLUMN paper.max_score IS '满分（恒 100）';
COMMENT ON COLUMN paper.created_at IS '创建时间（epoch ms）';
COMMENT ON COLUMN paper.submitted_at IS '交卷时间（epoch ms，可空）';

COMMENT ON TABLE question IS '题目：属于某张卷，卷内按 sequence 递增';
COMMENT ON COLUMN question.id IS '主键（自增）';
COMMENT ON COLUMN question.user_id IS '归属用户';
COMMENT ON COLUMN question.practice_id IS '所属练习（冗余，便于按练习查询）';
COMMENT ON COLUMN question.paper_id IS '所属卷';
COMMENT ON COLUMN question.sequence IS '卷内题号（从 1 开始）';
COMMENT ON COLUMN question.prompt IS '题面（大题含完整业务场景）';
COMMENT ON COLUMN question.reference_answer IS '参考答案（默认不给用户看）';
COMMENT ON COLUMN question.knowledge_points_json IS 'AI 标注的考察知识点 JSON 数组（仅供展示）';
COMMENT ON COLUMN question.demands_json IS '本题要求 JSON 数组（批改清单，从题面机械抽取）';
COMMENT ON COLUMN question.assigned_points_json IS '后端选点实际挂的知识点名 JSON 数组（掌握度回写依据）';
COMMENT ON COLUMN question.angle IS '出题角度（变种题避重的依据）';
COMMENT ON COLUMN question.tier IS '难度档 基础/中档/大题';
COMMENT ON COLUMN question.question_type IS '题型 概念辨析/简答/原理追问/场景应用/故障排查/方案设计';
COMMENT ON COLUMN question.points IS '本题分值（卷内合计 100）';
COMMENT ON COLUMN question.revealed_at IS '用户查看参考答案的时间（看了本题计 0 分）';
COMMENT ON COLUMN question.created_at IS '创建时间（epoch ms）';

COMMENT ON TABLE attempt IS '作答：追加保存，不覆盖历史；批改后写回评价';
COMMENT ON COLUMN attempt.id IS '主键（自增）';
COMMENT ON COLUMN attempt.user_id IS '归属用户';
COMMENT ON COLUMN attempt.question_id IS '所属题目';
COMMENT ON COLUMN attempt.sequence IS '该题的第几次作答（从 1 开始）';
COMMENT ON COLUMN attempt.answer IS '作答正文';
COMMENT ON COLUMN attempt.score IS 'AI 表现分 0-10';
COMMENT ON COLUMN attempt.points IS '实得分 = score/10 × 题目分值';
COMMENT ON COLUMN attempt.feedback IS '批改点评';
COMMENT ON COLUMN attempt.dimensions_json IS '维度分 JSON（场景分析/技术深度/表达结构）';
COMMENT ON COLUMN attempt.submitted_at IS '作答保存时间（epoch ms）';
COMMENT ON COLUMN attempt.evaluated_at IS '批改时间（epoch ms，未批改为空）';

COMMENT ON TABLE follow_up IS '追问聊天记录：按 question_id 隔离，每题一段独立会话';
COMMENT ON COLUMN follow_up.id IS '主键（自增）';
COMMENT ON COLUMN follow_up.user_id IS '归属用户';
COMMENT ON COLUMN follow_up.practice_id IS '所属练习';
COMMENT ON COLUMN follow_up.question_id IS '所属题目（会话隔离键）';
COMMENT ON COLUMN follow_up.role IS '角色 user/assistant';
COMMENT ON COLUMN follow_up.content IS '消息正文';
COMMENT ON COLUMN follow_up.created_at IS '创建时间（epoch ms）';

COMMENT ON TABLE knowledge_point IS '知识点：练习范围拆出的考点，出题与掌握度都挂在它上面';
COMMENT ON COLUMN knowledge_point.id IS '主键（自增）';
COMMENT ON COLUMN knowledge_point.user_id IS '归属用户';
COMMENT ON COLUMN knowledge_point.practice_id IS '所属练习';
COMMENT ON COLUMN knowledge_point.category IS '大类（用于分组展示）';
COMMENT ON COLUMN knowledge_point.name IS '知识点名';
COMMENT ON COLUMN knowledge_point.source IS '来源 scope（范围拆解）/answer（作答发散）';
COMMENT ON COLUMN knowledge_point.in_scope IS '是否在练习范围内';
COMMENT ON COLUMN knowledge_point.priority IS '面试重要度 high/medium/low（搜索取证分级）';
COMMENT ON COLUMN knowledge_point.evidence_json IS '重要度证据 JSON（可查）';
COMMENT ON COLUMN knowledge_point.bound_quick IS '速通档内容规格';
COMMENT ON COLUMN knowledge_point.bound_std IS '标准档内容规格';
COMMENT ON COLUMN knowledge_point.bound_deep IS '深挖档内容规格（天花板）';
COMMENT ON COLUMN knowledge_point.times_seen IS '被考过的次数（统计用）';
COMMENT ON COLUMN knowledge_point.history_json IS '历次作答证据 JSON 数组（最近 20 条）';
COMMENT ON COLUMN knowledge_point.angles_json IS '历次出题角度 JSON 数组（最近 5 条）';
COMMENT ON COLUMN knowledge_point.mastery IS '掌握度 0-100';
COMMENT ON COLUMN knowledge_point.status IS '状态 未学/学习中/待巩固/已掌握';
COMMENT ON COLUMN knowledge_point.created_at IS '创建时间（epoch ms）';
COMMENT ON COLUMN knowledge_point.updated_at IS '更新时间（epoch ms）';

COMMENT ON TABLE memory_point IS '记忆点：批改时 AI 给的「可直接背诵的一句话」';
COMMENT ON COLUMN memory_point.id IS '主键（自增）';
COMMENT ON COLUMN memory_point.user_id IS '归属用户';
COMMENT ON COLUMN memory_point.practice_id IS '所属练习';
COMMENT ON COLUMN memory_point.question_id IS '来源题目';
COMMENT ON COLUMN memory_point.point_names_json IS '挂靠的知识点名 JSON 数组';
COMMENT ON COLUMN memory_point.text IS '可背诵的一句话';
COMMENT ON COLUMN memory_point.created_at IS '创建时间（epoch ms）';

COMMENT ON TABLE mistake IS '错题本：per-practice，一题一条';
COMMENT ON COLUMN mistake.id IS '主键（自增）';
COMMENT ON COLUMN mistake.user_id IS '归属用户';
COMMENT ON COLUMN mistake.practice_id IS '所属练习';
COMMENT ON COLUMN mistake.question_id IS '题目（与 practice_id 联合去重）';
COMMENT ON COLUMN mistake.source IS '来源 auto（自动收录）/manual（手动）';
COMMENT ON COLUMN mistake.reason IS '错因 low-score/unanswered/revealed/manual';
COMMENT ON COLUMN mistake.score IS '收录时的表现分快照';
COMMENT ON COLUMN mistake.status IS '状态 open（待订正）/resolved（已订正）';
COMMENT ON COLUMN mistake.resolved_at IS '标记已订正的时间（epoch ms）';
COMMENT ON COLUMN mistake.created_at IS '收录时间（epoch ms）';
COMMENT ON COLUMN mistake.updated_at IS '更新时间（epoch ms）';

COMMENT ON TABLE note IS '【遗留】条目式练习笔记（已改用 practice.notes_text，当前为空表）';
COMMENT ON COLUMN note.id IS '主键（自增）';
COMMENT ON COLUMN note.user_id IS '归属用户';
COMMENT ON COLUMN note.practice_id IS '所属练习';
COMMENT ON COLUMN note.question_id IS '关联题目（可空）';
COMMENT ON COLUMN note.scene IS '场景 answering/grading/manual';
COMMENT ON COLUMN note.text IS '笔记正文';
COMMENT ON COLUMN note.created_at IS '创建时间（epoch ms）';
COMMENT ON COLUMN note.updated_at IS '更新时间（epoch ms）';

COMMENT ON TABLE review_doc IS '考前复习提纲：一个练习一份';
COMMENT ON COLUMN review_doc.id IS '主键（自增）';
COMMENT ON COLUMN review_doc.user_id IS '归属用户';
COMMENT ON COLUMN review_doc.practice_id IS '所属练习';
COMMENT ON COLUMN review_doc.status IS '状态 generating/ready/failed';
COMMENT ON COLUMN review_doc.content_json IS '【遗留】整份学习卡 JSON（已迁移到 review_card，不再读写）';
COMMENT ON COLUMN review_doc.progress_json IS '后台生成进度 JSON';
COMMENT ON COLUMN review_doc.created_at IS '创建时间（epoch ms）';
COMMENT ON COLUMN review_doc.updated_at IS '更新时间（epoch ms）';

COMMENT ON TABLE review_card IS '复习提纲学习卡：一份提纲按知识点一行';
COMMENT ON COLUMN review_card.id IS '主键（自增）';
COMMENT ON COLUMN review_card.user_id IS '归属用户';
COMMENT ON COLUMN review_card.review_doc_id IS '所属复习提纲';
COMMENT ON COLUMN review_card.point_name IS '知识点名（与 knowledge_point.name 对应）';
COMMENT ON COLUMN review_card.category IS '大类';
COMMENT ON COLUMN review_card.priority IS '优先级 high/medium/low';
COMMENT ON COLUMN review_card.content_json IS '单卡内容 JSON（必学/理解/选学三层）';
COMMENT ON COLUMN review_card.sequence IS '展示顺序（与知识点清单一致）';
COMMENT ON COLUMN review_card.created_at IS '创建时间（epoch ms）';
COMMENT ON COLUMN review_card.updated_at IS '更新时间（epoch ms）';

COMMENT ON TABLE source IS '网页抓取缓存：全局共享，按 URL 唯一，多用户复用';
COMMENT ON COLUMN source.id IS '主键（自增）';
COMMENT ON COLUMN source.url IS '网页 URL（唯一）';
COMMENT ON COLUMN source.title IS '网页标题';
COMMENT ON COLUMN source.text IS '抽取的正文纯文本（已截断）';
COMMENT ON COLUMN source.fetched_at IS '抓取时间（epoch ms）';
COMMENT ON COLUMN source.error IS '抓取失败原因（成功为空）';

COMMENT ON TABLE app_meta IS '应用元数据：迁移标记等';
COMMENT ON COLUMN app_meta.key IS '键';
COMMENT ON COLUMN app_meta.value IS '值';
